    center = true,
})

-- Telegram: float it, dim it when unfocused-ish, and keep the media viewer fully opaque
-- (ported from the old hyprland.conf windowrule/windowrulev2 + telegram { layerrule } block)
hl.window_rule({
    name  = "telegram-float",
    match = { class = "^(org.telegram.desktop)$" },

    float = true,
})

hl.window_rule({
    name  = "telegram-opacity",
    match = { class = "^(org.telegram.desktop)$" },

    opacity = "0.85",
})

hl.window_rule({
    name  = "telegram-media-viewer-opacity",
    match = { class = "^(org.telegram.desktop)$", title = "Media viewer" },

    opacity = "1.0 override", -- override, otherwise this multiplies with the 0.70 rule above
})

hl.layer_rule({
    name  = "telegram-blur",
    match = { namespace = "^(org.telegram.desktop)$" },

    blur         = true,
    ignore_alpha = true,
})

-- HyprMod managed settings
require("hyprland-gui")

-- For Noctalia Color templates
require("noctalia").apply_theme()
